#if UNITY_EDITOR
using System;
using System.Linq;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode { public class BCombatMigrationTests {
 static BCombatSlot[] Slots()=>new[]{new BCombatSlot("front"),new BCombatSlot("middle","op_kyle"),new BCombatSlot("rear","op_sable")};
 static BCombatFormation Formation(BCombatMode mode=BCombatMode.Solo)=>new BCombatFormation("train",mode,BCombatBattlefield.ExternalVertical,Slots());
 static BCombatHpBinding[] Bindings()=>new[]{new BCombatHpBinding("train",1000),new BCombatHpBinding("front",100),new BCombatHpBinding("middle",100),new BCombatHpBinding("rear",100),new BCombatHpBinding("op_kyle",200),new BCombatHpBinding("op_sable",200)};
 static BCombatLocalModel Model(int capacity=20)=>new BCombatLocalModel(Formation(),Bindings(),capacity,BCombatAuthority.UnitySolo);
 [Test] public void FormationUsesActualStableCarriageIdsAndCopiesInput(){var slots=Slots();var f=new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,slots);slots[0]=new BCombatSlot("replacement","op_sera");Assert.AreEqual("front",f.Slots[0].CarriageId);Assert.IsTrue(f.Slots[0].IsCargo);Assert.AreEqual("op_kyle",f.Slots[1].OperatorId);var copy=f.Capture();copy["slots"][1]["operatorId"]="op_mira";Assert.AreEqual("op_kyle",f.Slots[1].OperatorId);}
 [Test] public void FiveOperatorsAreNotALocomotiveSixthSlot(){var ids=new[]{"op_kyle","op_reina","op_eve","op_sera","op_mira"};var f=new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,ids.Select((id,i)=>new BCombatSlot("car"+i,id)));Assert.AreEqual(5,f.Slots.Count);Assert.Throws<ArgumentException>(()=>new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,f.Slots.Concat(new[]{new BCombatSlot("car6")})));}
 [Test] public void CargoDoesNotRequireExactlyOneOldCombatCar(){var f=new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,new[]{new BCombatSlot("cargo1"),new BCombatSlot("cargo2")});Assert.IsTrue(f.Slots.All(s=>s.IsCargo));}
 [TestCase("car")][TestCase("operator")][TestCase("train")][TestCase("candidate")]
 public void InvalidDeploymentIdentitiesCannotBecomeBSlots(string type){BCombatSlot[] slots=type=="car"?new[]{new BCombatSlot("car"),new BCombatSlot("car")}:type=="operator"?new[]{new BCombatSlot("car1","op_kyle"),new BCombatSlot("car2","op_kyle")}:type=="train"?new[]{new BCombatSlot("train")}:new[]{new BCombatSlot("car","op_rin")};Assert.Throws<ArgumentException>(()=>new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,slots));}
 [TestCase("op_kyle",0,0)][TestCase("op_reina",1,-1)][TestCase("op_eve",1,-1)][TestCase("op_sera",1,-1)][TestCase("op_mira",2,-1)][TestCase("op_vex",4,-1)][TestCase("op_nyx",2,-1)][TestCase("op_iris",1,-1)][TestCase("op_sable",0,1)][TestCase("op_marrow",1,-1)][TestCase("op_rail",0,-1)][TestCase("op_anchor",1,-1)][TestCase("op_lumen",2,-1)][TestCase("op_cinder",2,-1)][TestCase("op_warden",1,-1)]
 public void FifteenApprovedRolesKeepAttackAndInterceptionSeparate(string id,int attack,int interception){var range=BCombatRoleRanges.For(id);for(int target=0;target<5;target++){Assert.AreEqual(target<=attack,range.BasicAttackIncludesSlot(0,target,5));Assert.AreEqual(interception>=0&&target<=interception,range.InterceptionIncludesSlot(0,target,5));}Assert.AreEqual(interception<0?(int?)null:interception,range.InterceptionSlotRadius);}
 [Test] public void SlotEnvelopeDoesNotInventWorldDistanceOrSupportSkill(){var range=BCombatRoleRanges.For("op_vex");Assert.IsTrue(range.BasicAttackIncludesSlot(4,0,5));Assert.IsFalse(range.InterceptionIncludesSlot(4,0,5));Assert.Throws<ArgumentOutOfRangeException>(()=>range.BasicAttackIncludesSlot(4,5,5));Assert.Throws<ArgumentOutOfRangeException>(()=>range.InterceptionIncludesSlot(1,1,6));}
 [TestCase(BCombatMode.Solo,BCombatAuthority.UnitySolo)][TestCase(BCombatMode.Coop,BCombatAuthority.UnityCoopHost)][TestCase(BCombatMode.WorldSolo,BCombatAuthority.ServerWorld)][TestCase(BCombatMode.WorldCoop,BCombatAuthority.ServerWorld)]
 public void ModesKeepExistingAdjudicationOwnership(BCombatMode mode,BCombatAuthority owner){Assert.AreEqual(owner,Formation(mode).Authority);}
 [TestCase(BCombatMode.WorldSolo)][TestCase(BCombatMode.WorldCoop)] public void WorldCannotRunLocalHpKernel(BCombatMode mode){Assert.Throws<InvalidOperationException>(()=>new BCombatLocalModel(Formation(mode),Bindings(),20,BCombatAuthority.ServerWorld));}
 [Test] public void CoopOnlyExplicitHostLocalKernelCanApplyResolvedEvent(){Assert.Throws<InvalidOperationException>(()=>new BCombatLocalModel(Formation(BCombatMode.Coop),Bindings(),20,BCombatAuthority.UnitySolo));var host=new BCombatLocalModel(Formation(BCombatMode.Coop),Bindings(),20,BCombatAuthority.UnityCoopHost);host.ApplyResolvedSingleTargetDamage("e","op_kyle",20,1);Assert.AreEqual(180,host.Hp("op_kyle"));}
 [Test] public void SpecificInteriorNodeRemainsDistinctAndIsNotFakeSupportedExternal(){var f=new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.SpecificNodeInterior,Slots(),"special-node");Assert.AreEqual("special-node",f.InternalNodeId);Assert.Throws<InvalidOperationException>(()=>new BCombatLocalModel(f,Bindings(),20,BCombatAuthority.UnitySolo));Assert.Throws<ArgumentException>(()=>new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.SpecificNodeInterior,Slots()));}
 [Test] public void BrokenCarriageDoesNotKillMoveOrConvertItsOperator(){var m=Model();var before=Formation().Capture();m.ApplyResolvedSingleTargetDamage("car-hit","middle",100,1);Assert.AreEqual(0,m.Hp("middle"));Assert.AreEqual(200,m.Hp("op_kyle"));Assert.IsTrue(m.OperatorAlive("op_kyle"));Assert.AreEqual(1000,m.Hp("train"));Assert.IsTrue(JToken.DeepEquals(before,JObject.Parse(m.CaptureLocal())["definition"]["formation"]));}
 [Test] public void OperatorTrainAndCarriageResolvedHpAreIndependent(){var m=Model();m.ApplyResolvedSingleTargetDamage("operator-hit","op_kyle",200,1);Assert.IsFalse(m.OperatorAlive("op_kyle"));Assert.AreEqual(100,m.Hp("middle"));m.ApplyResolvedSingleTargetDamage("direct-train","train",30,2);Assert.AreEqual(970,m.Hp("train"));Assert.AreEqual(100,m.Hp("rear"));Assert.Throws<ArgumentException>(()=>m.OperatorAlive("front"));}
 [Test] public void DuplicateOriginalEventReturnsOriginalReceiptWithoutSecondDamage(){var m=Model();var r=m.ApplyResolvedSingleTargetDamage("e","op_sable",30,1);m.ApplyResolvedSingleTargetDamage("later","op_sable",30,2);var before=m.CaptureLocal();Assert.AreSame(r,m.ApplyResolvedSingleTargetDamage("e","op_sable",30,1));Assert.AreEqual(before,m.CaptureLocal());Assert.Throws<InvalidOperationException>(()=>m.ApplyResolvedSingleTargetDamage("e","train",30,1));Assert.AreEqual(before,m.CaptureLocal());}
 [Test] public void RestoreReplaysOriginalEventsAndRequiresOriginalProfile(){var m=Model();m.ApplyResolvedSingleTargetDamage("car","middle",100,1);m.ApplyResolvedSingleTargetDamage("op","op_sable",70,2);var json=m.CaptureLocal();var r=BCombatLocalModel.RestoreLocal(json,Formation(),Bindings(),20,BCombatAuthority.UnitySolo);Assert.AreEqual(json,r.CaptureLocal());Assert.IsTrue(r.OperatorAlive("op_kyle"));Assert.AreEqual(130,r.Hp("op_sable"));var altered=Bindings();altered[0]=new BCombatHpBinding("train",2000);Assert.Throws<ArgumentException>(()=>BCombatLocalModel.RestoreLocal(json,Formation(),altered,20,BCombatAuthority.UnitySolo));}
 [TestCase("hp")][TestCase("formation")][TestCase("duplicate")][TestCase("schema")]
 public void CorruptLocalSnapshotDoesNotBecomeAcceptedRunState(string bad){var m=Model();m.ApplyResolvedSingleTargetDamage("e","middle",10,1);var saved=JObject.Parse(m.CaptureLocal());if(bad=="hp")saved["vitals"]["middle"]["hp"]=99;else if(bad=="formation")saved["definition"]["formation"]["slots"][0]["operatorId"]="op_sera";else if(bad=="duplicate")((JArray)saved["events"]).Add(saved["events"][0].DeepClone());else saved["schema"]="legacy-A";Assert.Throws<ArgumentException>(()=>BCombatLocalModel.RestoreLocal(saved.ToString(),Formation(),Bindings(),20,BCombatAuthority.UnitySolo));}
 [Test] public void FailureOnCapacityOrOldClockIsAtomic(){var m=Model(1);m.ApplyResolvedSingleTargetDamage("e","middle",10,1);var before=m.CaptureLocal();Assert.Throws<InvalidOperationException>(()=>m.ApplyResolvedSingleTargetDamage("next","op_kyle",20,2));Assert.AreEqual(before,m.CaptureLocal());var c=Model();c.ApplyResolvedSingleTargetDamage("first","middle",1,10);before=c.CaptureLocal();Assert.Throws<InvalidOperationException>(()=>c.ApplyResolvedSingleTargetDamage("old","op_kyle",1,9));Assert.AreEqual(before,c.CaptureLocal());}
 [Test] public void TickOutsideRestorableRangeCannotMutateHp(){var m=Model();var before=m.CaptureLocal();Assert.Throws<ArgumentException>(()=>m.ApplyResolvedSingleTargetDamage("e","op_kyle",1,9007199254740992L));Assert.AreEqual(before,m.CaptureLocal());}
 [Test] public void EveryAdmittedMaximumEscapedEventCacheCanRestore(){var m=Model(10000);for(int i=0;i<6000;i++)m.ApplyResolvedSingleTargetDamage(i.ToString("D5")+new string('\u0001',123),"middle",0,i);var json=m.CaptureLocal();Assert.Greater(json.Length,4194304);var restored=BCombatLocalModel.RestoreLocal(json,Formation(),Bindings(),10000,BCombatAuthority.UnitySolo);Assert.AreEqual(json,restored.CaptureLocal());}
 [Test] public void HpBindingsCannotShareOrOmitOwners(){Assert.Throws<ArgumentException>(()=>new BCombatLocalModel(Formation(),Bindings().Take(5),20,BCombatAuthority.UnitySolo));Assert.Throws<ArgumentException>(()=>new BCombatLocalModel(Formation(),Bindings().Concat(new[]{Bindings()[0]}),20,BCombatAuthority.UnitySolo));}
 }}
#endif
